def submit_subtask(
    session: requests.Session,
    bearer: str,
    guest_token: str,
    flow_token: str,
    subtask_id: str,
    subtask_type: str,
    payload: dict,
    *,
    verbose: bool = True,
) -> requests.Response:
    """回答一个子任务:POST {flow_token, subtask_inputs:[{subtask_id, <type>:{...}}]}。"""
    body = {
        "flow_token": flow_token,
        "subtask_inputs": [{"subtask_id": subtask_id, subtask_type: payload}],
    }
    if verbose:
        print("  [submit] %s (%s)" % (subtask_id, subtask_type))
    return onboarding_task(session, bearer, guest_token, body=body, verbose=verbose)


def start_signup_flow(session: requests.Session, verbose: bool = True):
    """换 bearer + guest + 启动 signup flow。返回 (bearer, guest, response)。"""
    bearer = get_bearer(session, verbose=verbose) or FALLBACK_BEARER
    guest = guest_activate(session, bearer, verbose=verbose)
    if not guest:
        return bearer, None, None
    body = {
        "input_flow_data": {
            "flow_context": {"start_location": {"location": "splash_screen"}}
        },
        "subtask_versions": DEFAULT_SUBTASK_VERSIONS,
    }
    r = onboarding_task(session, bearer, guest, flow_name="signup", body=body, verbose=verbose)
    return bearer, guest, r


