// js_inst_solver.js — 用 Node 跑 X 的 js_instrumentation 混淆 JS,产出 response token
// ============================================================================
// X 注册 Signup 子任务带一个 js_instrumentation 挑战:GET /i/js_inst?native=true
// → HTML 壳 → /i/js_inst?native=true&native_js=true → 混淆 JS。该 JS 算出
//   {'rf':{...算术混淆验证值...},'s':'<服务器给的base64>'},经
//   window.location = "/?result=" + JSON.stringify(...) 上报。
// 本求解器:从 stdin 读 JS,加最小 DOM shim(JS 只用 createElement/getElementsByTagName/
// window.location),eval 后捕获 window.location 的赋值 → 打到 stdout。
// 输出 = "/?result={...}";调用方取 result= 之后的 JSON 串作 response。

let js = '';
process.stdin.on('data', d => js += d);
process.stdin.on('end', () => {
  let captured = null;

  // 任意属性访问 / 调用都返回自身的 Proxy(让 createElement().X.Y() 之类不崩)
  function mockElement() {
    return new Proxy(function () {}, {
      get: (t, p) => {
        if (p === 'style') return {};
        if (p === Symbol.toPrimitive) return () => '';
        if (p === 'length') return 0;
        return mockElement();
      },
      set: () => true,
      apply: () => mockElement(),
      construct: () => mockElement(),
    });
  }

  global.document = {
    createElement: () => mockElement(),
    getElementsByTagName: () => [mockElement()],
  };
  global.window = {};
  Object.defineProperty(global.window, 'location', {
    set(v) { captured = v; },
    get() { return {}; },
    configurable: true,
  });

  try {
    // 非严格 eval:函数声明 hoist 到本作用域,末尾的自调用会执行并赋值 window.location
    eval(js);
  } catch (e) {
    if (captured === null) captured = '/?result=exception ' + e;
  }
  process.stdout.write(String(captured || ''));
});

