def solve_js_instrumentation(
    session: requests.Session, bearer: str, guest_token: str, *, verbose: bool = True
) -> Optional[str]:
    """跑 X 的 js_instrumentation 挑战(Node + DOM shim)→ 返回 response token 串。

    GET /i/js_inst?native=true → HTML 壳 → native_js JS → Node eval 捕获 window.location
    → 取 result= 之后的 JSON({'rf':{...},'s':'...'})作 js_instrumentation.response。
    """
    h = client_headers()
    h["Authorization"] = "Bearer " + bearer
    h["x-guest-token"] = guest_token
    html = session.get(
        "https://twitter.com/i/js_inst?native=true", headers=h, timeout=30
    ).text
    m = re.search(r'src="([^"]+)"', html)
    if not m:
        if verbose:
            print("  [js_inst] 没找到 native_js src;html:", html[:120])
        return None
    js_url = m.group(1)
    if js_url.startswith("/"):
        js_url = "https://twitter.com" + js_url
    js = session.get(js_url, headers=h, timeout=30).text
    try:
        p = subprocess.run(
            ["node", _JS_SOLVER], input=js, capture_output=True, text=True, timeout=30
        )
    except FileNotFoundError:
        if verbose:
            print("  [js_inst] node 不可用")
        return None
    out = (p.stdout or "").strip()
    if "result=" in out:
        resp = out.split("result=", 1)[1]
    else:
        resp = out
    if resp.startswith("exception"):
        if verbose:
            print("  [js_inst] JS 异常:", resp[:160])
        return None
    if verbose:
        print("  [js_inst] solved, response len=%d (head: %s…)" % (len(resp), resp[:40]))
    return resp


