// js_inst_solver.js — 用 Node 跑 X 的 js_instrumentation 混淆 JS,产出 response token
// ============================================================================
// X 注册 Signup 子任务带 js_instrumentation 挑战:GET /i/js_inst?native=true → HTML 壳
// → /i/js_inst?native=true&native_js=true → 混淆 JS。该 JS 算出
//   {'rf':{...},'s':'<服务器给的base64>'},经 window.location = "/?result="+JSON.stringify(...) 上报。
//
// **关键**:rf 的部分值由一个真 DOM 树编解码算法算出(mmRvs 按值 bit 建 div 树、设 innerText,
// ZvKmL 沿 parentNode 往上累加 innerText 再 %256)。用到 createElement/appendChild/children/
// parentNode/innerText/removeChild/lastElementChild。**必须实现正确的真 DOM**,否则 rf 错、
// 服务器回 "Missing data"。这里实现最小但行为正确的 DOM(只覆盖算法用到的操作)。
//
// 用法:stdin 喂 JS → stdout 输出 "/?result={...}";调用方取 result= 之后的 JSON 作 response。

let js = '';
process.stdin.on('data', d => (js += d));
process.stdin.on('end', () => {
  let captured = null;

  class El {
    constructor() {
      this.children = [];
      this.parentNode = null;
      this._innerText = '';
    }
    setAttribute() {}
    appendChild(c) { c.parentNode = this; this.children.push(c); return c; }
    removeChild(c) {
      const i = this.children.indexOf(c);
      if (i >= 0) this.children.splice(i, 1);
      if (c) c.parentNode = null;
      return c;
    }
    get lastElementChild() {
      return this.children.length ? this.children[this.children.length - 1] : null;
    }
    set innerText(v) { this._innerText = String(v); }
    get innerText() { return this._innerText; }
  }

  const body = new El();
  global.document = {
    createElement: () => new El(),
    getElementsByTagName: (t) => (t === 'body' ? [body] : [body]),
    documentElement: body,
    body: body,
    head: body,
  };
  global.window = {};
  Object.defineProperty(global.window, 'location', {
    set(v) { captured = v; },
    get() { return {}; },
    configurable: true,
  });
  global.navigator = { userAgent: 'Mozilla/5.0 (Linux; Android 14)' };

  try {
    eval(js); // 非严格:函数声明 hoist,末尾自调用执行并赋值 window.location
  } catch (e) {
    if (captured === null) captured = '/?result=exception ' + (e && e.message ? e.message : e);
  }
  process.stdout.write(String(captured || ''));
});

