// js_inst_solver.js — 用 Node 跑 X 的 js_instrumentation 混淆 JS,产出 response token
// ============================================================================
// X 注册 Signup 子任务带 js_instrumentation 挑战:GET /i/js_inst?native=true → HTML 壳
// → /i/js_inst?native=true&native_js=true → 混淆 JS。该 JS 算出
//   {'rf':{...算术混淆验证值...},'s':'<服务器给的base64>'},经
//   window.location = "/?result=" + JSON.stringify(...) 上报。
// 本求解器:从 stdin 读 JS,加最小 DOM shim(JS 只用 createElement/getElementsByTagName +
// window.location),eval 后捕获 window.location 赋值 → 打到 stdout = "/?result={...}"。
//
// shim 用**单例共享 Proxy**(避免每次属性访问新建对象 → 栈溢出);强制类型转换
// (valueOf/toString/Symbol.toPrimitive)返回原始值;symbol 属性返回 undefined。
// DOM 调用是反 headless 诱饵,值不进 rf 计算(经验:服务器接受即证)。

let js = '';
process.stdin.on('data', d => (js += d));
process.stdin.on('end', () => {
  let captured = null;

  const handler = {
    get(t, p) {
      if (p === Symbol.toPrimitive || p === 'valueOf') return () => 0;
      if (p === 'toString') return () => '';
      if (typeof p === 'symbol') return undefined;
      if (p === 'length') return 0;
      return el; // 链式访问返回同一个共享 proxy
    },
    set: () => true,
    apply: () => el,
    construct: () => el,
  };
  const el = new Proxy(function () {}, handler);

  global.document = {
    createElement: () => el,
    getElementsByTagName: () => [el],
    documentElement: el,
    body: el,
    head: el,
  };
  global.window = {};
  Object.defineProperty(global.window, 'location', {
    set(v) { captured = v; },
    get() { return {}; },
    configurable: true,
  });
  global.navigator = { userAgent: 'Mozilla/5.0 (Linux; Android 14)' };

  try {
    eval(js); // 非严格:函数声明 hoist,末尾自调用执行并赋值 window.location
  } catch (e) {
    if (captured === null) captured = '/?result=exception ' + (e && e.message ? e.message : e);
  }
  process.stdout.write(String(captured || ''));
});

